INSERT INTO SiteSettings (id, companyName, tagline, aboutText, heroTitle, heroSubtitle, heroImage, email, phone, whatsappNumber, address, gstNumber, bankDetails, socialLinks, stats, features)
VALUES ('default', 'Trip Master', 'Curating Bespoke Luxury Journeys Across India & Beyond', 'At Trip Master, we believe travel should be more than a booking — it should be an effortless, soul-enriching experience. For over 15 years, our specialist curators have crafted personalized holiday packages across the globe, pairing handpicked 5-star sanctuaries with dedicated 24/7 on-ground concierge support.', 'Your next unforgettable journey starts here.', 'Curated holiday packages, trusted by thousands of happy travellers.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=2400&q=85', 'concierge@tripmaster.in', '+91 98765 43210', '+91 98765 43210', 'The Oberoi Grand Arc, Level 4, MG Road, Bengaluru, Karnataka 560001', '29AABCU9603R1ZX', '', '{"instagram":"https://instagram.com/tripmasterluxury","facebook":"https://facebook.com/tripmastertravel","twitter":"https://x.com/tripmaster","linkedin":"https://linkedin.com/company/tripmaster"}', '[{"label":"Happy Travellers","value":"10,000+","icon":"Users","description":"Trusted by thousands of satisfied travellers worldwide"},{"label":"Verified Rating (Google Reviews)","value":"4.8 / 5","icon":"Star","description":"Based on 2,500+ authentic traveler reviews"},{"label":"Years of Experience","value":"15+","icon":"Calendar","description":"Crafting bespoke and stress-free holiday escapes"}]', '[{"title":"Bespoke Personalization","description":"Every itinerary is tailored from scratch around your culinary preferences, pace, and private celebrations.","icon":"Sparkles"},{"title":"Vetted Heritage & 5-Star Stays","description":"Direct partnerships with Oberoi, Taj, Khyber, and secluded luxury estate owners with complimentary room upgrades.","icon":"Building"},{"title":"Private Chauffeured Fleet","description":"Sanitized premium luxury sedans and SUVs with vetted English-fluent chauffeur captains and bottled artisanal water.","icon":"Car"},{"title":"24/7 Dedicated Trip Concierge","description":"A personal concierge assigned to your booking via direct WhatsApp hotline before, during, and after your expedition.","icon":"Headphones"}]')
ON CONFLICT (id) DO UPDATE SET heroTitle = EXCLUDED.heroTitle, heroSubtitle = EXCLUDED.heroSubtitle, stats = EXCLUDED.stats;

INSERT INTO Package (id, title, slug, destination, durationDays, durationNights, basePrice, discountedPrice, featuredImage, galleryImages, overview, mapCoordinates, inclusions, exclusions, paymentPolicy, cancellationPolicy, isFeatured, isPublished, viewsCount)
VALUES ('cmw3rbzsz000112o1i8ly7fsl', 'Kashmir Celestial Serenade: Gulmarg Gondola & Dal Royal Houseboat', 'kashmir-celestial-serenade', 'Kashmir, India', 6, 5, 125000, 98000, 'https://images.unsplash.com/photo-1598091383021-15ddea10925d?auto=format&fit=crop&w=1600&q=85', '["https://images.unsplash.com/photo-1598091383021-15ddea10925d?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1566837945700-30057527ade0?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1620641788421-7a1c342ea42e?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=85"]', 'Surrender to the crown of the Himalayas. Glide through the lotus-dappled waters of Dal Lake on a private Shikara, sleep under hand-carved cedar ceilings in a luxury heritage houseboat, soar to 14,000 feet on the Gulmarg Gondola Phase II, and stroll through the saffron plains and pine pine-scented meadows of Pahalgam.', '[{"name":"Srinagar (Dal Lake)","lat":34.0837,"lng":74.7973},{"name":"Gulmarg Meadows","lat":34.0484,"lng":74.3805},{"name":"Pahalgam Valley of Shepherds","lat":34.0163,"lng":75.315},{"name":"Aru Valley Sanctuary","lat":34.0921,"lng":75.2638}]', '["5 Nights accommodation in 5-star luxury resorts & premium lake-facing houseboat","Daily gourmet breakfast & 4-course royal Kashmiri Wazwan dinner experience","Private chauffeur-driven luxury SUV (Innova Crysta / Toyota Fortuner) throughout","VIP Priority tickets for Gulmarg Gondola Phase 1 & Phase 2","Sunset 2-hour private Shikara cruise on Dal Lake with hot Kashmiri Kahwa","All toll taxes, parking, driver allowances, and 24/7 dedicated trip manager"]', '["Domestic or International flights to/from Srinagar International Airport (SXR)","Pony rides and private sledging in Gulmarg & Pahalgam (can be pre-booked upon request)","Personal expenses, laundry, telephone calls, and alcoholic beverages","Travel and medical insurance (available as an optional add-on)"]', '30% advance deposit required at time of confirmation. Balance 70% payable 15 days prior to arrival. Razorpay Credit/Debit cards, UPI, and Bank Transfers accepted.', 'Free cancellation up to 21 days before travel date with 100% refund. 50% refund between 20 to 10 days. Non-refundable within 9 days of travel.', TRUE, TRUE, 1421)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO ItineraryDay (id, packageId, dayNumber, title, description, mealsIncluded, activityPhotos, accommodationName, accommodationPhoto, accommodationRating, accommodationCategory, accommodationDetails)
VALUES ('cmw3rbzsz000212o167fkb6nm', 'cmw3rbzsz000112o1i8ly7fsl', 1, 'Royal Arrival in Srinagar & Sunset Shikara on Dal Lake', 'Arrive at Srinagar International Airport where your private Trip Master chauffeur welcomes you with traditional saffron Kahwa. Transfer to your luxury heritage houseboat stationed on Dal Lake. In the evening, embark on a serene 2-hour Shikara ride observing floating flower gardens and Char Chinar island against the twilight Pir Panjal peaks.', '["Dinner"]', '["https://images.unsplash.com/photo-1598091383021-15ddea10925d?auto=format&fit=crop&w=800&q=80"]', 'Sukoon Luxury Dal Lake Houseboat', 'https://images.unsplash.com/photo-1566837945700-30057527ade0?auto=format&fit=crop&w=800&q=80', 5, 'Luxury Resort', 'Eco-luxury hand-carved pinewood suite with heated cedar bathrooms and private sundeck looking into the Zabarwan mountain range.')
ON CONFLICT (packageId, dayNumber) DO NOTHING;

INSERT INTO ItineraryDay (id, packageId, dayNumber, title, description, mealsIncluded, activityPhotos, accommodationName, accommodationPhoto, accommodationRating, accommodationCategory, accommodationDetails)
VALUES ('cmw3rbzsz000312o1ix2nwj8s', 'cmw3rbzsz000112o1i8ly7fsl', 2, 'Mughal Gardens Heritage Walk & Old Srinagar Artisan Bazaars', 'Visit Nishat Bagh (Garden of Bliss) and Shalimar Bagh (Abode of Love) built by Emperor Jahangir. Afternoon private visit to master Pashmina weavers and walnut woodcarvers in the historic downtown Srinagar. Savor authentic multi-course Wazwan delicacies prepared by master Wazas.', '["Breakfast","Dinner"]', '["https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80"]', 'The Lalit Grand Palace Srinagar', 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?auto=format&fit=crop&w=800&q=80', 4.9, 'Luxury Resort', 'Historic palace built in 1910 by Maharaja Pratap Singh surrounded by sprawling Chinar groves.')
ON CONFLICT (packageId, dayNumber) DO NOTHING;

INSERT INTO ItineraryDay (id, packageId, dayNumber, title, description, mealsIncluded, activityPhotos, accommodationName, accommodationPhoto, accommodationRating, accommodationCategory, accommodationDetails)
VALUES ('cmw3rbzsz000412o1n7gi7f2n', 'cmw3rbzsz000112o1i8ly7fsl', 3, 'Ascent to Gulmarg: Meadow of Flowers & Phase II Gondola', 'Scenic drive through apple orchards to Gulmarg. Check into the renowned Khyber Himalayan Resort. Board the Gulmarg Gondola Phase 1 (Kongdoori) and Phase 2 soaring to Apharwat Peak at 13,780 feet for panoramic vistas of Nanga Parbat. Evening relaxation by the heated indoor infinity pool.', '["Breakfast","Dinner"]', '["https://images.unsplash.com/photo-1551632811-561732d1e306?auto=format&fit=crop&w=800&q=80"]', 'The Khyber Himalayan Resort & Spa', 'https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&fit=crop&w=800&q=80', 5, 'Luxury Resort', 'World-renowned alpine luxury resort offering floor-to-ceiling mountain views and L''Occitane Spa.')
ON CONFLICT (packageId, dayNumber) DO NOTHING;

INSERT INTO ItineraryDay (id, packageId, dayNumber, title, description, mealsIncluded, activityPhotos, accommodationName, accommodationPhoto, accommodationRating, accommodationCategory, accommodationDetails)
VALUES ('cmw3rbzt0000512o1fakg4bww', 'cmw3rbzsz000112o1i8ly7fsl', 4, 'Journey to Pahalgam: Valley of Shepherds & Lidder River', 'Drive through the saffron fields of Pampore and walnut forests along the roaring turquoise Lidder River to Pahalgam. Check in at your riverside cottage retreat. Afternoon at leisure breathing pristine Himalayan cedar air, with an optional private horse trail into Baisaran Meadow.', '["Breakfast","Dinner"]', '["https://images.unsplash.com/photo-1620641788421-7a1c342ea42e?auto=format&fit=crop&w=800&q=80"]', 'Pahalgam Hotel & River Cottages', 'https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?auto=format&fit=crop&w=800&q=80', 4.8, 'Luxury Resort', 'Luxury wooden suites located directly on the embankment of the sparkling Lidder river.')
ON CONFLICT (packageId, dayNumber) DO NOTHING;

INSERT INTO ItineraryDay (id, packageId, dayNumber, title, description, mealsIncluded, activityPhotos, accommodationName, accommodationPhoto, accommodationRating, accommodationCategory, accommodationDetails)
VALUES ('cmw3rbzt0000612o1qt128k1i', 'cmw3rbzsz000112o1i8ly7fsl', 5, 'Hidden Valleys of Aru & Betaab & Riverside High Tea', 'Explore Betaab Valley with its lush meadows framed by snow-dusted crags, followed by the pastoral village of Aru Valley. Enjoy an exclusive curated riverside High Tea set up by our team featuring Kashmiri walnut cookies, fresh orchard fruits, and piping Kahwa.', '["Breakfast","Dinner"]', '["https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80"]', 'Pahalgam Hotel & River Cottages', 'https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?auto=format&fit=crop&w=800&q=80', 4.8, 'Luxury Resort', 'Private evening bonfire under the clear Himalayan night sky.')
ON CONFLICT (packageId, dayNumber) DO NOTHING;

INSERT INTO ItineraryDay (id, packageId, dayNumber, title, description, mealsIncluded, activityPhotos, accommodationName, accommodationPhoto, accommodationRating, accommodationCategory, accommodationDetails)
VALUES ('cmw3rbzt0000712o12v6v9olr', 'cmw3rbzsz000112o1i8ly7fsl', 6, 'Farewell to Paradise: Scenic Return to Srinagar Airport', 'Relish a lazy champagne breakfast overlooking the Lidder River. Chauffeur transfer back to Srinagar Airport for your scheduled departure, carrying timeless memories of the Valley of the Gods.', '["Breakfast"]', '[]', 'Departure / Return Flight', NULL, 5, 'Luxury Resort', 'VIP airport drop-off with assisted baggage transfer.')
ON CONFLICT (packageId, dayNumber) DO NOTHING;

INSERT INTO Package (id, title, slug, destination, durationDays, durationNights, basePrice, discountedPrice, featuredImage, galleryImages, overview, mapCoordinates, inclusions, exclusions, paymentPolicy, cancellationPolicy, isFeatured, isPublished, viewsCount)
VALUES ('cmw3rbzt1000812o10s5uhxzt', 'Kerala Sovereign Backwaters, Tea Sanctuaries & Marari Sands', 'kerala-sovereign-backwaters', 'Kerala, India', 6, 5, 110000, 89000, 'https://images.unsplash.com/photo-1602216056096-3b40cc0c9944?auto=format&fit=crop&w=1600&q=85', '["https://images.unsplash.com/photo-1602216056096-3b40cc0c9944?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1593693397690-362cb9666fc2?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=1200&q=85"]', 'Unwind in God''s Own Country. From the mist-draped tea carpet hills of Munnar to private luxury houseboats cruising through secret palm-canopied canals of Kumarakom, capped off with barefoot luxury villas overlooking the Arabian Sea in Marari.', '[{"name":"Cochin International Airport","lat":10.1556,"lng":76.3916},{"name":"Munnar Tea Plantations","lat":10.0889,"lng":77.0595},{"name":"Kumarakom Lake Canals","lat":9.6175,"lng":76.4301},{"name":"Marari Secluded Beach","lat":9.6006,"lng":76.2999}]', '["5 Nights in luxury heritage pool villas & private 1-bedroom air-conditioned Kettuvallam houseboat","All meals on the private houseboat freshly prepared by dedicated on-board chef","Daily lavish gourmet buffet breakfast at all luxury resorts","Private chauffeur-driven premium air-conditioned luxury vehicle throughout the tour","Curated spice plantation tour and private tea tasting session in Munnar","Complimentary 60-minute Ayurvedic rejuvenation couple massage at Kumarakom"]', '["Airfares to/from Cochin International Airport (COK)","Optional water sports at Marari Beach","Personal expenses, gratuities, and alcoholic beverages"]', '25% advance to block luxury pool villas and houseboat. Balance 75% payable 10 days before departure.', '100% refund up to 14 days prior to travel. 50% refund within 7 to 13 days.', TRUE, TRUE, 2180)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO ItineraryDay (id, packageId, dayNumber, title, description, mealsIncluded, activityPhotos, accommodationName, accommodationPhoto, accommodationRating, accommodationCategory, accommodationDetails)
VALUES ('cmw3rbzt2000912o1n603v1ix', 'cmw3rbzt1000812o10s5uhxzt', 1, 'Cochin to the Cloud-Kissed Tea Estates of Munnar', 'Arrive in Cochin and journey up the Western Ghats past Cheeyappara waterfalls to Munnar. Check into your mountain villa nestled amidst emerald tea estates. Enjoy evening high tea on your terrace overlooking rolling mist.', '["Dinner"]', '["https://images.unsplash.com/photo-1593693397690-362cb9666fc2?auto=format&fit=crop&w=800&q=80"]', 'Fragrant Nature Munnar (Luxury Highlands)', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=800&q=80', 4.9, 'Luxury Resort', 'Trophy-winning colonial hill resort with private fireplace and panoramic views of tea hills.')
ON CONFLICT (packageId, dayNumber) DO NOTHING;

INSERT INTO ItineraryDay (id, packageId, dayNumber, title, description, mealsIncluded, activityPhotos, accommodationName, accommodationPhoto, accommodationRating, accommodationCategory, accommodationDetails)
VALUES ('cmw3rbzt2000a12o12g3mecg1', 'cmw3rbzt1000812o10s5uhxzt', 2, 'Private Tea Factory Tour & Eravikulam Nilgiri Tahr Encounter', 'Morning guided walk with a certified botanist through century-old tea gardens and a private artisanal factory to craft your custom tea blend. Afternoon visit to Eravikulam National Park, home of the endangered Nilgiri Tahr.', '["Breakfast","Dinner"]', '["https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=800&q=80"]', 'Fragrant Nature Munnar', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=800&q=80', 4.9, 'Luxury Resort', 'Private candlelight dinner in the tea gardens.')
ON CONFLICT (packageId, dayNumber) DO NOTHING;

INSERT INTO ItineraryDay (id, packageId, dayNumber, title, description, mealsIncluded, activityPhotos, accommodationName, accommodationPhoto, accommodationRating, accommodationCategory, accommodationDetails)
VALUES ('cmw3rbzt2000b12o1e0m5ncky', 'cmw3rbzt1000812o10s5uhxzt', 3, 'Descent to Kumarakom: Vembanad Lake & Luxury Backwater Resort', 'Descend from the hills to the tranquil banks of Vembanad Lake in Kumarakom. Check into Kumarakom Lake Resort. Afternoon traditional Ayurvedic rejuvenation therapy and private sunset cruise with classical flute recitals.', '["Breakfast","Dinner"]', '["https://images.unsplash.com/photo-1602216056096-3b40cc0c9944?auto=format&fit=crop&w=800&q=80"]', 'Kumarakom Lake Resort (Heritage Pool Villa)', 'https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=800&q=80', 5, 'Luxury Resort', '16th-century reconstructed traditional Kerala courtyard villas with private plunge pool.')
ON CONFLICT (packageId, dayNumber) DO NOTHING;

INSERT INTO ItineraryDay (id, packageId, dayNumber, title, description, mealsIncluded, activityPhotos, accommodationName, accommodationPhoto, accommodationRating, accommodationCategory, accommodationDetails)
VALUES ('cmw3rbzt2000c12o15m11dbbj', 'cmw3rbzt1000812o10s5uhxzt', 4, 'Private Houseboat Odyssey: Canals, Karimeen & Starlit Waters', 'Board your private, fully crewed air-conditioned luxury Kettuvallam houseboat. Cruise through the narrow palm-fringed canals of Alleppey. Your private chef serves freshly caught Pearl Spot (Karimeen Pollichathu) and Kerala coconut curries.', '["Breakfast","Lunch","Dinner"]', '["https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?auto=format&fit=crop&w=800&q=80"]', 'Spice Coast Signature Private Houseboat', 'https://images.unsplash.com/photo-1593693397690-362cb9666fc2?auto=format&fit=crop&w=800&q=80', 4.9, 'Luxury Resort', 'Ultra-exclusive single-bedroom luxury houseboat anchored in quiet secluded backwater bays under the stars.')
ON CONFLICT (packageId, dayNumber) DO NOTHING;

INSERT INTO ItineraryDay (id, packageId, dayNumber, title, description, mealsIncluded, activityPhotos, accommodationName, accommodationPhoto, accommodationRating, accommodationCategory, accommodationDetails)
VALUES ('cmw3rbzt2000d12o1yqe4446q', 'cmw3rbzt1000812o10s5uhxzt', 5, 'Marari Beach Coastal Sanctuary & Fresh Seafood Barbecue', 'Disembark after morning tea on the water and transfer to the powdery sands of Marari. Spend the day walking barefoot along tranquil fishing hamlets or relaxing in hammocks. Evening beach bonfire with gourmet seafood barbecue.', '["Breakfast","Dinner"]', '["https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80"]', 'Marari Beach Resort - CGH Earth', 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=800&q=80', 4.8, 'Luxury Resort', 'Eco-luxury thatched cottage suites surrounded by organic butterfly gardens and coconut groves.')
ON CONFLICT (packageId, dayNumber) DO NOTHING;

INSERT INTO ItineraryDay (id, packageId, dayNumber, title, description, mealsIncluded, activityPhotos, accommodationName, accommodationPhoto, accommodationRating, accommodationCategory, accommodationDetails)
VALUES ('cmw3rbzt2000e12o1e3ryfzaq', 'cmw3rbzt1000812o10s5uhxzt', 6, 'Cochin Heritage Stroll & Departure', 'Morning transfer to historic Fort Kochi to witness the iconic 14th-century Chinese Fishing Nets and Jew Town spice warehouses before your chauffeur drops you at Cochin International Airport.', '["Breakfast"]', '[]', 'Airport Transfer', NULL, 5, 'Luxury Resort', 'Seamless airport transfer with express check-in guidance.')
ON CONFLICT (packageId, dayNumber) DO NOTHING;

INSERT INTO Package (id, title, slug, destination, durationDays, durationNights, basePrice, discountedPrice, featuredImage, galleryImages, overview, mapCoordinates, inclusions, exclusions, paymentPolicy, cancellationPolicy, isFeatured, isPublished, viewsCount)
VALUES ('cmw3rbzt3000f12o1l7mllcsp', 'Andaman Sovereign Islands: Havelock Turquoise & Neil Coral Eden', 'andaman-sovereign-islands', 'Andaman Islands, India', 6, 5, 135000, 105000, 'https://images.unsplash.com/photo-1589394815804-964ed0be2eb5?auto=format&fit=crop&w=1600&q=85', '["https://images.unsplash.com/photo-1589394815804-964ed0be2eb5?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1510414842594-a61752af3337?auto=format&fit=crop&w=1200&q=85"]', 'Indulge in India''s most pristine tropical paradise. Pure azure waters, white powder sand voted Asia''s best at Radhanagar Beach, private luxury catamarans, and untouched coral reefs in Havelock and Neil Island with private beach villa stays.', '[{"name":"Port Blair Capital","lat":11.6234,"lng":92.7265},{"name":"Havelock Island (Swaraj Dweep)","lat":11.9761,"lng":92.9876},{"name":"Radhanagar Beach No. 7","lat":11.9835,"lng":92.9515},{"name":"Neil Island (Shaheed Dweep)","lat":11.8322,"lng":93.0505}]', '["5 Nights in ocean-view luxury beach villas & 5-star private island resorts","Royal Class premium tickets on high-speed luxury catamarans (Makruzz / Nautika)","Daily lavish breakfast and curated beachside dinners","Exclusive private sunset dinner setup at Radhanagar Beach","Guided private snorkeling excursion with PADI certified dive master at Elephant Beach","Private transfers in air-conditioned luxury SUVs on all islands"]', '["Airfare to/from Veer Savarkar International Airport Port Blair (IXZ)","Scuba diving certifications (optional add-on available)","Personal expenses and premium alcoholic spirits"]', '30% advance on booking, balance due 20 days prior to island arrival.', 'Full refund up to 30 days prior. 50% refund up to 15 days prior.', TRUE, TRUE, 1850)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO ItineraryDay (id, packageId, dayNumber, title, description, mealsIncluded, activityPhotos, accommodationName, accommodationPhoto, accommodationRating, accommodationCategory, accommodationDetails)
VALUES ('cmw3rbzt3000g12o1ua0szdzi', 'cmw3rbzt3000f12o1l7mllcsp', 1, 'Port Blair Arrival & Historic Cellular Jail Light & Sound', 'Touch down at Port Blair where our concierge welcomes you. Transfer to your luxury cliffside resort overlooking the Andaman Sea. Evening private VIP seating at the Cellular Jail Light & Sound show narrating India''s struggle for independence.', '["Dinner"]', '["https://images.unsplash.com/photo-1589394815804-964ed0be2eb5?auto=format&fit=crop&w=800&q=80"]', 'Welcomhotel By ITC Hotels, Bay Island', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=800&q=80', 4.8, 'Luxury Resort', 'Designed by legendary architect Charles Correa with native Padauk wood suites looking out to the harbor.')
ON CONFLICT (packageId, dayNumber) DO NOTHING;

INSERT INTO ItineraryDay (id, packageId, dayNumber, title, description, mealsIncluded, activityPhotos, accommodationName, accommodationPhoto, accommodationRating, accommodationCategory, accommodationDetails)
VALUES ('cmw3rbzt3000h12o1jzmpdk03', 'cmw3rbzt3000f12o1l7mllcsp', 2, 'Luxury Catamaran to Havelock & Radhanagar Sunset', 'Board the Makruzz Royal Class catamaran slicing across cobalt waters to Havelock Island (Swaraj Dweep). Check in to Taj Exotica Resort & Spa. Late afternoon excursion to Radhanagar Beach (Beach No. 7), ranked amongst the finest beaches in the world.', '["Breakfast","Dinner"]', '["https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80"]', 'Taj Exotica Resort & Spa, Andamans', 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?auto=format&fit=crop&w=800&q=80', 5, 'Luxury Resort', 'Sprawling 46-acre sanctuary with luxury stilted villas under coconut canopies, steps away from pristine shoreline.')
ON CONFLICT (packageId, dayNumber) DO NOTHING;

INSERT INTO ItineraryDay (id, packageId, dayNumber, title, description, mealsIncluded, activityPhotos, accommodationName, accommodationPhoto, accommodationRating, accommodationCategory, accommodationDetails)
VALUES ('cmw3rbzt3000i12o1hfj6sfw0', 'cmw3rbzt3000f12o1l7mllcsp', 3, 'Private Speedboat to Elephant Beach Reefs & Snorkeling', 'Private chartered speedboat to the secluded reefs of Elephant Beach. Enjoy private guided snorkeling amongst untouched staghorn corals, sea turtles, and clownfish with a certified PADI marine naturalist. Afternoon spa indulgence at Jiva Spa.', '["Breakfast","Dinner"]', '["https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=800&q=80"]', 'Taj Exotica Resort & Spa, Andamans', 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?auto=format&fit=crop&w=800&q=80', 5, 'Luxury Resort', 'Curated beachside dining under lantern-lit banyan trees.')
ON CONFLICT (packageId, dayNumber) DO NOTHING;

INSERT INTO ItineraryDay (id, packageId, dayNumber, title, description, mealsIncluded, activityPhotos, accommodationName, accommodationPhoto, accommodationRating, accommodationCategory, accommodationDetails)
VALUES ('cmw3rbzt3000j12o15f75dl7p', 'cmw3rbzt3000f12o1l7mllcsp', 4, 'Escape to Neil Island: Natural Coral Bridge & Bharatpur Beach', 'Cruise to Neil Island (Shaheed Dweep), an oasis of slow island life. Visit the magnificent Howrah Bridge—a geological natural limestone rock arch formation. Relax on the lagoon waters of Bharatpur beach.', '["Breakfast","Dinner"]', '["https://images.unsplash.com/photo-1510414842594-a61752af3337?auto=format&fit=crop&w=800&q=80"]', 'Sea Shell Samssara Neil Island', 'https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=800&q=80', 4.8, 'Luxury Resort', 'Chic beachside pool villas offering private boardwalks onto quiet coral beaches.')
