INSERT INTO Package (id, title, slug, destination, durationDays, durationNights, basePrice, discountedPrice, featuredImage, galleryImages, overview, mapCoordinates, inclusions, exclusions, paymentPolicy, cancellationPolicy, isFeatured, isPublished, viewsCount)
VALUES ('cmw3rbzt5000m12o1pdcuqewr', 'Rajasthan Sovereign Royalty: Lake Palace, Blue City & Amber Fortress', 'rajasthan-sovereign-royalty', 'Rajasthan, India', 6, 5, 145000, 119000, 'https://images.unsplash.com/photo-1599661046289-e31897846e41?auto=format&fit=crop&w=1600&q=85', '["https://images.unsplash.com/photo-1599661046289-e31897846e41?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1524492412937-b28074a5d7da?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1585123388867-3bfe6dd4bdbf?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1477587458883-47145ed94245?auto=format&fit=crop&w=1200&q=85"]', 'Relive the grandeur of the Rajput Maharajas. Cruise the shimmering waters of Lake Pichola to your private island palace in Udaipur, marvel at the towering ramparts of Mehrangarh in Jodhpur, and enter the pink-hued gates and amber bastions of Jaipur with royal historians.', '[{"name":"Udaipur Lake Pichola","lat":24.5764,"lng":73.6835},{"name":"Ranakpur Jain Temples","lat":25.1163,"lng":73.4735},{"name":"Jodhpur Blue City & Mehrangarh","lat":26.2978,"lng":73.0185},{"name":"Jaipur Pink City & Amber Fort","lat":26.9855,"lng":75.8513}]', '["5 Nights in authentic royal heritage palace suites (Taj / Oberoi / Raas)","Daily royal champagne breakfast and 4-course Rajputana thali dinners","Private chauffeur-driven Mercedes / BMW / Toyota Fortuner throughout","Private solar boat cruise to Jagmandir Island Palace on Lake Pichola","Curated private tour of Mehrangarh Fort with a royal family curator","All palace entry tickets, camera permits, and monument concierge access"]', '["Airfares to Udaipur (UDR) and from Jaipur (JAI)","Hot air balloon ride over Jaipur (optional booking available)","Personal purchases of gemstones, textiles, and antique crafts"]', '25% confirmation deposit, 75% payable 14 days before check-in.', '100% refund up to 21 days before arrival date. 50% refund up to 10 days prior.', TRUE, TRUE, 3120)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO ItineraryDay (id, packageId, dayNumber, title, description, mealsIncluded, activityPhotos, accommodationName, accommodationPhoto, accommodationRating, accommodationCategory, accommodationDetails)
VALUES ('cmw3rbzt5000n12o1ogw6g45o', 'cmw3rbzt5000m12o1pdcuqewr', 1, 'Udaipur: Venice of the East & Lake Pichola Private Boat', 'Arrive in Udaipur. Arrive at the private jetty where your royal boat awaits to ferry you across Lake Pichola. Check in to your palace suite. Afternoon private visit to the City Palace complex followed by a candlelit rooftop dinner overlooking the illuminated lake.', '["Dinner"]', '["https://images.unsplash.com/photo-1599661046289-e31897846e41?auto=format&fit=crop&w=800&q=80"]', 'Taj Lake Palace, Udaipur', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=800&q=80', 5, 'Luxury Resort', 'Legendary 18th-century white marble palace floating in the center of Lake Pichola.')
