INSERT INTO FAQ (id, question, answer, category, isPublished, order)
VALUES ('cmw4w1w0r0000icabemrv5q3e', 'How do I book a holiday package?', 'Booking with Trip Master is completely seamless and guest-friendly with zero login friction. Simply click "Plan My Trip" or "Explore" on your preferred package. You can choose to reserve your slot directly with a 25% token advance via Razorpay, or request a custom itinerary quote. A dedicated travel manager will confirm all flight connections, room preferences, and vouchers within 4 hours.', 'Booking', TRUE, 1)
ON CONFLICT (id) DO NOTHING;

INSERT INTO FAQ (id, question, answer, category, isPublished, order)
VALUES ('cmw4w1w0t0001icabwqhqfjz9', 'Are your packages customisable?', 'Yes, 100%. Every package is a flexible blueprint designed to be tailored to your specific schedule, party size, and luxury preferences. We can adjust the duration, upgrade your villa or suite, arrange private chartered yachts or helicopter transfers, and accommodate special culinary and dietary requests.', 'Customisation', TRUE, 2)
ON CONFLICT (id) DO NOTHING;

INSERT INTO FAQ (id, question, answer, category, isPublished, order)
VALUES ('cmw4w1w0u0002icabnnp7eyu7', 'What is included in the package price?', 'Our pricing is transparent and comprehensive. All packages include vetted 4★ and 5★ accommodations, daily gourmet breakfast, private chauffeured luxury SUVs/sedans with professional captains, priority sightseeing passes, airport VIP meet & greet, and 24/7 concierge support. We never charge hidden surcharges.', 'Pricing & Inclusions', TRUE, 3)
ON CONFLICT (id) DO NOTHING;

INSERT INTO FAQ (id, question, answer, category, isPublished, order)
VALUES ('cmw4w1w0u0003icabldxmklm8', 'What are your payment and cancellation policies?', 'We offer flexible payment terms: you can lock your reservation with a 25% booking token deposit, with the remaining balance due 15 days before departure. We also offer 100% full refund cancellation up to 14–21 days prior to your travel date, clearly detailed on every booking voucher.', 'Policies', TRUE, 4)
ON CONFLICT (id) DO NOTHING;

INSERT INTO FAQ (id, question, answer, category, isPublished, order)
VALUES ('cmw4w1w0v0004icabt6lhjuze', 'Will I have support during my trip?', 'Yes. From arrival to departure, you will have a personal on-ground Trip Concierge available 24/7 via phone and WhatsApp. They monitor flight schedules, arrange seamless hotel check-ins, manage route chauffeurs, and assist with restaurant reservations in real-time.', 'Support', TRUE, 5)
ON CONFLICT (id) DO NOTHING;

